def insert(root, key):
    if root is None:
        return [key, None, None]
    node = root
    while True:
        if key == node[0]:
            return root
        side = 1 if key < node[0] else 2
        if node[side] is None:
            node[side] = [key, None, None]
            return root
        node = node[side]

root = None
for key in [2, 1, 3, 2]:
    root = insert(root, key)
print(root)
